Hier ist eine C++-Funktion, die auf einen `std::string` mit Markdown-formatiertem Text verweist und einen `std::string` mit HTML-formatiertem Text zurückgibt, basierend auf dem [Pandoc-Converter](https://pandoc.org/):

```cpp
#include <iostream>
#include <sstream>
#include <string>
#include <pandoc/include/pandoc/include.h>

using namespace std;

string convertMarkdownToHtml(const string& markdown) {
    // Create Pandoc options and input/output files
    PandocOptions options;
    options.input_format = "markdown";
    options.output_format = "html";
    options.output_file = "";
    stringstream ss;
    ss << "md_input" << endl;
    options.input_file = ss.str().c_str();

    // Convert Markdown to HTML
    int ret = pandoc_convert(&options, NULL);

    // Check for errors
    if (ret != 0) {
        throw runtime_error("Pandoc conversion failed");
    }

    // Read HTML output from temporary file
    string html_output;
    ifstream input(options.output_file);
    if (input.is_open()) {
        string line;
        while (getline(input, line)) {
            html_output += line;
        }
        input.close();
    } else {
        throw runtime_error("Failed to open Pandoc output file");
    }

    // Clean up temporary files
    pandoc_cleanup();

    return html_output;
}

int main() {
    string markdown = "# Hello, World! \nThis is a **markdown** string. ";
    string html = convertMarkdownToHtml(markdown);
    cout << html << endl;
    return 0;
}
```

